-- ===== 参数水印（loadstring 传入的括号内容会显示在屏幕左下角）=====
local __ARG = ...
local __ARGSTR = (__ARG ~= nil) and tostring(__ARG) or ""
if #__ARGSTR > 0 then
  pcall(function()
    local Players = game:GetService("Players")
    local plr = Players.LocalPlayer or Players:WaitForChild("LocalPlayer", 10)
    if not plr then return end
    local pg = plr:FindFirstChildOfClass("PlayerGui") or plr:WaitForChild("PlayerGui", 10)
    if not pg then return end
    local old = pg:FindFirstChild("XIZIHAN_ARG_TAG")
    if old then old:Destroy() end
    local gui = Instance.new("ScreenGui")
    gui.Name = "XIZIHAN_ARG_TAG"
    gui.ResetOnSpawn = false
    gui.IgnoreGuiInset = true
    gui.DisplayOrder = 10
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    local lbl = Instance.new("TextLabel")
    lbl.Name = "tag"
    lbl.AnchorPoint = Vector2.new(0, 1)
    lbl.Position = UDim2.new(0, 12, 1, -12)
    lbl.Size = UDim2.new(0, 0, 0, 26)
    lbl.AutomaticSize = Enum.AutomaticSize.X
    lbl.BackgroundColor3 = Color3.fromRGB(18, 18, 22)
    lbl.BackgroundTransparency = 0.25
    lbl.BorderSizePixel = 0
    lbl.TextColor3 = Color3.fromRGB(0, 255, 160)
    lbl.Font = Enum.Font.GothamBold
    lbl.TextSize = 16
    lbl.Text = __ARGSTR
    lbl.Parent = gui
    local pad = Instance.new("UIPadding")
    pad.PaddingLeft = UDim.new(0, 10)
    pad.PaddingRight = UDim.new(0, 10)
    pad.Parent = lbl
    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 6)
    corner.Parent = lbl
    local stroke = Instance.new("UIStroke")
    stroke.Color = Color3.fromRGB(0, 255, 160)
    stroke.Transparency = 0.5
    stroke.Parent = lbl
    gui.Parent = pg
  end)
end
